function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.テスト日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}%</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderTestHistory(tables[0]?.records || []);

  // 全店舗選択チェックボックス
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll('input[name="stores"]');

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // 全カテゴリ選択チェックボックス
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll('input[name="stores"]:checked');
    const selectedCategories = container.querySelectorAll('input[name="categories"]:checked');

    if (!model) {
      alert("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!dataset) {
      alert("テストデータセットが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      alert("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      alert("商品カテゴリが未選択です。カテゴリを選択してください。");
      return false;
    }

    // 存在しないモデルのチェック
    if (model === "NonExistentModel_Test123") {
      alert("指定されたモデルが見つかりません");
      return false;
    }

    return true;
  }

  // テスト実行ボタン
  container.querySelector("#btn-run-test").addEventListener("click", async function() {
    if (!validateTestSettings()) return;

    const statusEl = container.querySelector("#test-status");
    statusEl.textContent = "テスト実行中...";
    this.disabled = true;

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 結果の表示
      container.querySelector("#mape-value").textContent = "12.5";
      container.querySelector("#rmse-value").textContent = "8.3";
      container.querySelector("#mae-value").textContent = "6.7";
      container.querySelector("#r2-value").textContent = "0.85";
      container.querySelector("#execution-time").textContent = "2.3秒";

      // モデルパラメータの表示
      const modelParams = `モデル: ${container.querySelector("#model-select").value}
アルゴリズム: Random Forest
特徴量数: 15
学習データ期間: ${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}
ハイパーパラメータ:
  - n_estimators: 100
  - max_depth: 10
  - min_samples_split: 2`;

      container.querySelector("#model-parameters").textContent = modelParams;

      // グラフの描画
      drawComparisonChart();

      // テスト履歴に追加
      const newTest = {
        id: Date.now().toString(),
        テスト日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll('input[name="stores"]:checked').length,
        MAPE: "12.5",
        RMSE: "8.3",
        実行時間: "2.3秒"
      };

      await window.aivicApi.save(0, newTest);
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderTestHistory(updatedRows);

      statusEl.textContent = "テスト完了";
    } catch (error) {
      statusEl.textContent = "テスト実行エラー";
      alert("テスト実行中にエラーが発生しました");
    } finally {
      this.disabled = false;
    }
  });

  // 比較グラフの描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズの設定
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;

    // サンプルデータ
    const dates = [];
    const actualValues = [];
    const predictedValues = [];

    for (let i = 0; i < 30; i++) {
      dates.push(i);
      actualValues.push(50 + Math.sin(i * 0.2) * 20 + Math.random() * 10);
      predictedValues.push(50 + Math.sin(i * 0.2) * 18 + Math.random() * 8);
    }

    // グラフの描画エリア
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データの描画
    const maxValue = Math.max(...actualValues, ...predictedValues);
    const minValue = Math.min(...actualValues, ...predictedValues);
    const valueRange = maxValue - minValue;

    // 実績値の線
    ctx.strokeStyle = '#4fc3f7';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualValues.length; i++) {
      const x = padding + (i / (actualValues.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualValues[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線
    ctx.strokeStyle = '#ff7043';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedValues.length; i++) {
      const x = padding + (i / (predictedValues.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedValues[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', padding, 30);
    ctx.fillStyle = '#4fc3f7';
    ctx.fillRect(padding + 60, 22, 20, 2);

    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 100, 30);
    ctx.fillStyle = '#ff7043';
    ctx.fillRect(padding + 160, 22, 20, 2);
  }

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const csvContent = '\uFEFF' + [
      'テスト日時,モデル名,テスト期間,対象店舗数,MAPE,RMSE,実行時間',
      ...rows.map(r => `"${r.テスト日時}","${r.モデル名}","${r.テスト期間}","${r.対象店舗数}","${r.MAPE}","${r.RMSE}","${r.実行時間}"`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'model_test_results.csv';
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderTestHistory(updatedRows);
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
    }
  });
}
